executor_dual_registry.snippet:
export function createExecutor(type: TaskType): TaskExecutor {
  switch (type) {
    case 'chat': return new ChatTaskExecutor()
    case 'agent': return new AgentTaskExecutor()
    case 'skill': return new SkillTaskExecutor()
    default: return new ChatTaskExecutor()
  }
}

export function createContextAwareExecutor(type: TaskType): ContextAwareExecutor {
  switch (type) {
    case 'chat': return new ChatAgentExecutor(createChatProvider())
    case 'agent': return new AgentTaskExecutor()
    case 'skill': return new SkillTaskExecutor()
    default: return new ChatAgentExecutor(createChatProvider())
  }
}

